/* style.css (à ajouter à votre CSS) */
body { margin: 0; font-family: sans-serif; }
header { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; padding: 12px; background: #7b3f00; color: white; }
nav a { color: white; margin: 0 8px; text-decoration: none; }
#menuBtn { display: none; }
main { padding: 16px; }
.cartes { display: flex; flex-wrap: wrap; gap: 12px; }
.carte { flex: 1 1 200px; border: 1px solid #ddd; border-radius: 10px; padding: 12px; }
@media (max-width: 600px) {
  #menuBtn { display: block; }
  nav { display: none; width: 100%; }
  nav.ouvert { display: block; }
  nav a { display: block; padding: 10px 0; }
}

// script.js
document.getElementById("menuBtn").addEventListener("click", function () {
  document.getElementById("menu").classList.toggle("ouvert");
});
